import java.util.*;

class Solution {
    public boolean wordBreak(String s, List<String> wordDict) {
        return f(s, new HashSet<>(wordDict), 0);
    }

    private boolean f(String s, Set<String> set, int start) {
        if (start == s.length()) return true;
        for (int end = start + 1; end <= s.length(); end++) {
            if (set.contains(s.substring(start, end)) && f(s, set, end)) return true;
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public boolean wordBreak(String s, List<String> wordDict) {
        Boolean[] memo = new Boolean[s.length() + 1];
        return f(s, new HashSet<>(wordDict), 0, memo);
    }

    private boolean f(String s, Set<String> set, int start, Boolean[] memo) {
        if (start == s.length()) return true;
        if (memo[start] != null) return memo[start];

        for (int end = start + 1; end <= s.length(); end++) {
            if (set.contains(s.substring(start, end)) && f(s, set, end, memo)) {
                memo[start] = true;
                return true;
            }
        }
        memo[start] = false;
        return false;
    }
}

import java.util.*;

class Solution {
    public boolean wordBreak(String s, List<String> wordDict) {
        int n = s.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;

        for (int i = 1; i <= n; i++) {
            for (String word : wordDict) {
                int len = word.length();
                if (len > i) continue;
                if (!dp[i - len]) continue;
                if (!s.startsWith(word, i - len)) continue;
                dp[i] = true;
                break;
            }
        }
        return dp[n];
    }
}
